head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST20034";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst20034.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "findDigitalIsurCdIcSub");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", "list");
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20034.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst20034.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20034.btn_fnSearchInit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/findDigitalIsurCdIc.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name reflectCorpName
 * @description reflect Corp Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.reflectCorpName = function () {
    let listApplntIsurNm = $c.util.getComponent('ipt_listApplntIsurNm').getValue();
    listApplntIsurNm = encodeURI(listApplntIsurNm);
    $c.util.getComponent('ipt_listApplntIsurNm').getValue();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.setCodeName();
    scwin.reflectCorpName();
    $c.util.getComponent('ipt_beginIndex').setValue("");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
};

/**
 * @method
 * @name setDigitallistApplntInfo
 * @description set Digitallist Applnt Info 처리
 * @param {String} ipt_listApplntIsurCd ipt_listApplntIsurCd
 * @param {String} listApplntIsurNm listApplntIsurNm
 * @returns {void}
 * @hidden N
 */
scwin.setDigitallistApplntInfo = function (ipt_listApplntIsurCd, listApplntIsurNm) {
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setDigitallistApplntInfo === 'function' ? (scwin.openerScwin()).setDigitallistApplntInfo(ipt_listApplntIsurCd, listApplntIsurNm) : void 0), $c.win.closePopup([ipt_listApplntIsurCd, listApplntIsurNm]));
    this.close();
};

/**
 * @method
 * @name setCodeName
 * @description set Code Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCodeName = function () {
    $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
    $c.util.getComponent('ipt_listApplntIsurNm').setValue("");
    let listApplntIsu = $c.util.getComponent('ipt_listApplntIsu').getValue(); if (listApplntIsu == null) { listApplntIsu = ''; }
    listApplntIsu = listApplntIsu.toUpperCase();
    if (listApplntIsu == null) {
        return;
    }
    if (listApplntIsu === "") {
        return;
    }
    $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
    $c.util.getComponent('ipt_listApplntIsurNm').setValue(listApplntIsu);
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
